# codec plugin

// 辅助函数，用于替换每一个匹配到的 &#...; 字符串
htmlEntityReplacer = func(match) {
	// 提取出数字部分，例如从 "M" 中提取出 "77"
	codeStr := match[2:len(match)-1]

	codePoint, err := atoi(codeStr)
	if err != nil {
		return match
	}

	// 使用 sprintf 函数，并指定 "%c" (character) 格式化动词，
	// 将整数码点强制格式化为它所代表的单个字符。
	return sprintf("%c", codePoint)
}

// 主处理函数
handle = func(origin) {
	regexObj, err := re.Compile(`&#(\d+);`)
	if err != nil {
		return origin
	}

	// 调用替换函数
	result := regexObj.ReplaceAllStringFunc(origin, htmlEntityReplacer)

	return result
}
